#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    cin >> n >> x >> pos;

    // Precompute factorials up to n
    vector<long long> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    // Fermat's little theorem for modular inverse
    auto mod_pow = [&](long long a, long long e) {
        long long res = 1;
        while (e) {
            if (e & 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    };
    inv_fact[n] = mod_pow(fact[n], MOD - 2);
    for (int i = n; i >= 1; --i) {
        inv_fact[i - 1] = inv_fact[i] * i % MOD;
    }
    auto C = [&](int N, int K) -> long long {
        if (K < 0 || K > N) return 0;
        return fact[N] * inv_fact[K] % MOD * inv_fact[N - K] % MOD;
    };

    int left = 0, right = n;
    int less_count = 0, greater_count = 0;
    while (left < right) {
        int mid = (left + right) / 2;
        if (mid <= pos) {
            if (mid != pos) less_count++;
            left = mid + 1;
        } else {
            greater_count++;
            right = mid;
        }
    }

    int available_less = x - 1;
    int available_greater = n - x;

    if (less_count > available_less || greater_count > available_greater) {
        cout << 0 << "\n";
        return 0;
    }

    long long ans = 1;
    // Choose numbers for less positions and arrange them
    ans = ans * C(available_less, less_count) % MOD * fact[less_count] % MOD;
    // Choose numbers for greater positions and arrange them
    ans = ans * C(available_greater, greater_count) % MOD * fact[greater_count] % MOD;
    // Remaining numbers can be arranged arbitrarily
    int remaining = n - 1 - less_count - greater_count;
    ans = ans * fact[remaining] % MOD;

    cout << ans << "\n";
    return 0;
}
