    vector<long long> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    inv_fact[n] = modpow(fact[n]);
    for (int i = n; i > 0; --i) inv_fact[i - 1] = inv_fact[i] * i % MOD;

    int less = x - 1;      // numbers smaller than x
    int greater = n - x;   // numbers greater than x

    int needLess = 0, needGreater = 0;
    int l = 0, r = n;
    while (l < r) {
        int mid = (l + r) / 2;
        if (mid == pos) {
            l = mid + 1;
        } else if (mid < pos) {
            // mid must be less than x
            ++needLess;
            l = mid + 1;
        } else { // mid > pos
            // mid must be greater than x
            ++needGreater;
            r = mid;
        }
    }

    if (needLess > less || needGreater > greater) {
        cout << 0 << "\n";
        return 0;
    }

    long long ans = 1;
    // Choose which numbers go to the "less" positions and arrange them: P(less, needLess)
    ans = ans * fact[less] % MOD * inv_fact[less - needLess] % MOD;
    // Choose which numbers go to the "greater" positions and arrange them: P(greater, needGreater)
    ans = ans * fact[greater] % MOD * inv_fact[greater - needGreater] % MOD;
    // The remaining positions can be filled arbitrarily with the remaining numbers
    int remaining = n - 1 - needLess - needGreater;
    ans = ans * fact[remaining] % MOD;

    cout << ans % MOD << "\n";
    return 0;
}
