#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int addmod(int a, int b) { a+=b; if(a>=MOD) a-=MOD; return a; }
int mulmod(long long a, long long b) { return int((a*b)%MOD); }
int powmod(int a, int e) { long long r=1, b=a; while(e){ if(e&1) r=r*b%MOD; b=b*b%MOD; e>>=1; } return int(r); }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, x, pos;
    if(!(cin >> n >> x >> pos)) return 0;
    vector<int> fact(n+1), invfact(n+1);
    fact[0] = 1;
    for(int i=1;i<=n;i++) fact[i] = mulmod(fact[i-1], i);
    invfact[n] = powmod(fact[n], MOD-2);
    for(int i=n;i>=1;i--) invfact[i-1] = mulmod(invfact[i], i);
    auto P = [&](int N, int K)->int {
        if(K<0 || K>N) return 0;
        return mulmod(fact[N], invfact[N-K]);
    };

    int less = 0, greater = 0;
    int l = 0, r = n;
    while(l < r) {
        int mid = (l + r) / 2;
        if(mid == pos) {
            l = mid + 1;
        } else if(mid < pos) {
            less++;
            l = mid + 1;
        } else { // mid > pos
            greater++;
            r = mid;
        }
    }

